<?php
require_once __DIR__.'/bootstrap.php';
// Small deterministic PDF renderer. User text is escaped as PDF strings; no HTML or remote resources are executed.
function tdc_pdf(array $lines):string{
 $settings=db()->query("SELECT setting_key,setting_value FROM site_settings WHERE setting_key LIKE 'invoice_%'")->fetchAll(PDO::FETCH_KEY_PAIR);
 if(is_file(__DIR__.'/../vendor/autoload.php')){require_once __DIR__.'/pdf_layout.php';return tdc_layout_pdf($lines,$settings);}
 $font=in_array($settings['invoice_font']??'', ['Helvetica','Times-Roman','Courier'],true)?$settings['invoice_font']:'Helvetica';
 $hex=$settings['invoice_color']??'#3354aa';if(!preg_match('/^#[a-f0-9]{6}$/i',$hex))$hex='#3354aa';$rgb=array_map(fn($p)=>hexdec($p)/255,str_split(substr($hex,1),2));
 $escape=static fn($t)=>str_replace(['\\','(',')',"\r","\n"],['\\\\','\\(','\\)',' ',' '],iconv('UTF-8','Windows-1252//TRANSLIT',(string)$t)?:'');
 $wrapped=[];foreach($lines as $line){$text=iconv('UTF-8','Windows-1252//TRANSLIT',(string)$line)?:'';foreach(explode("\n",wordwrap($text,88,"\n",true)) as $chunk)$wrapped[]=mb_convert_encoding($chunk,'UTF-8','Windows-1252');}$pages=array_chunk($wrapped,38);if(!$pages)$pages=[[]];$objects=[1=>'<< /Type /Catalog /Pages 2 0 R >>',2=>'',3=>'<< /Type /Font /Subtype /Type1 /BaseFont /'.$font.' /Encoding /WinAnsiEncoding >>'];$kids=[];
 foreach($pages as $i=>$page){$pid=4+$i*2;$cid=$pid+1;$kids[]=$pid.' 0 R';$stream=implode(' ',$rgb)." rg 0 760 595 82 re f\n1 1 1 rg BT /F1 22 Tf 40 794 Td (".$escape($settings['invoice_header']??'TDC TECH').") Tj ET\n0.12 0.12 0.15 rg BT /F1 11 Tf 40 735 Td 17 TL\n";foreach($page as $line){foreach([$escape($line)] as $chunk)$stream.='('.$chunk.") Tj T*\n";}$stream.="ET\nBT /F1 9 Tf 40 38 Td (".$escape(($settings['invoice_footer']??'TDC TECH | tdctech.org').' | Page '.($i+1).'/'.count($pages)).") Tj ET";$objects[$pid]='<< /Type /Page /Parent 2 0 R /MediaBox [0 0 595 842] /Resources << /Font << /F1 3 0 R >> >> /Contents '.$cid.' 0 R >>';$objects[$cid]='<< /Length '.strlen($stream).">>\nstream\n".$stream."\nendstream";}
 $objects[2]='<< /Type /Pages /Count '.count($pages).' /Kids ['.implode(' ',$kids).'] >>';ksort($objects);$pdf="%PDF-1.4\n";$offsets=[0];foreach($objects as $id=>$obj){$offsets[$id]=strlen($pdf);$pdf.=$id." 0 obj\n".$obj."\nendobj\n";}$xref=strlen($pdf);$pdf.='xref'."\n0 ".(count($objects)+1)."\n0000000000 65535 f \n";foreach($objects as $id=>$obj)$pdf.=sprintf('%010d 00000 n ',$offsets[$id])."\n";$pdf.='trailer << /Size '.(count($objects)+1).' /Root 1 0 R >>'."\nstartxref\n".$xref."\n%%EOF";return $pdf;
}
function tdc_invoice(int $id):array{$q=db()->prepare('SELECT o.*,s.name service,u.name,u.email FROM orders o JOIN services s ON s.id=o.service_id JOIN users u ON u.id=o.user_id WHERE o.id=?');$q->execute([$id]);$o=$q->fetch();if(!$o)throw new InvalidArgumentException('Order not found');return [$o,['INVOICE INV-'.str_pad((string)$id,6,'0',STR_PAD_LEFT),'Date: '.$o['created_at'],'Billed to: '.$o['name'],'Email: '.$o['email'],'Order: #'.$id,'Service: '.$o['service'],'Description: '.$o['description'],'Amount: EUR '.number_format((float)$o['amount'],2),'Payment: Wallet','Order status: '.$o['status'],'','Keep this invoice for your records.']];}
function queue_document_email(int $uid,string $subject,array $lines,string $filename):void{require_once __DIR__.'/notifications.php';$root=__DIR__.'/../storage/documents';if(!is_dir($root))mkdir($root,0750,true);$stored=bin2hex(random_bytes(20)).'.pdf';file_put_contents($root.'/'.$stored,tdc_pdf($lines));chmod($root.'/'.$stored,0640);$q=db()->prepare('SELECT email FROM users WHERE id=?');$q->execute([$uid]);$email=$q->fetchColumn();if(!$email||tdc_email_suppressed($email))return;db()->prepare("INSERT INTO notification_outbox(user_id,recipient_email,subject,body_text,attachments_json,status,created_at,updated_at) VALUES(?,?,?,?,?,'queued',UTC_TIMESTAMP(),UTC_TIMESTAMP())")->execute([$uid,$email,$subject,implode("\n",$lines),json_encode([['stored'=>$stored,'name'=>$filename]])]);}
